import { CONSTANTS, utilities as csUtils, } from '@cornerstonejs/core';
import { getViewportPresentation } from './viewportPresentation.js';
const { RENDERING_DEFAULTS } = CONSTANTS;
export function getSlabThicknessOrDefault(viewport) {
    if (csUtils.isGenericViewport(viewport)) {
        return RENDERING_DEFAULTS.MINIMUM_SLAB_THICKNESS;
    }
    return viewport.getSlabThickness();
}
export function getViewSlabDepthOfViewport(viewport) {
    const slabThickness = viewport.getSlabThickness?.();
    if (!Number.isFinite(slabThickness)) {
        return undefined;
    }
    return csUtils.getViewSlabDepth(csUtils.isGenericViewport(viewport) ? slabThickness : slabThickness * 2);
}
export function jumpToFocalPoint(viewport, cameraFocalPoint) {
    if (csUtils.isGenericViewport(viewport)) {
        viewport.setViewReference({ cameraFocalPoint });
    }
}
export function navigatePlanarViewportToPoint(viewport, worldPoint) {
    if (!csUtils.isGenericViewport(viewport)) {
        return false;
    }
    const isStackContent = viewport.getCurrentMode?.() === 'stack';
    if (isStackContent) {
        const stackViewport = viewport;
        if (typeof stackViewport.getImageIds !== 'function' ||
            typeof stackViewport.getCurrentImageIdIndex !== 'function') {
            return false;
        }
        let imageIndex = null;
        try {
            imageIndex = csUtils.getClosestStackImageIndexForPoint(worldPoint, stackViewport);
        }
        catch {
            return false;
        }
        if (imageIndex === null || imageIndex < 0) {
            return false;
        }
        viewport.setViewReference({
            sliceIndex: imageIndex,
        });
        return true;
    }
    viewport.setViewReference({
        cameraFocalPoint: [worldPoint[0], worldPoint[1], worldPoint[2]],
    });
    return true;
}
export function getNativeSourceProperties(viewport) {
    if (!csUtils.viewportSupportsDisplaySetPresentation(viewport)) {
        return { properties: {} };
    }
    const sourceDataId = viewport.getSourceDataId();
    const properties = {
        ...((sourceDataId
            ? viewport.getDisplaySetPresentation(sourceDataId)
            : {}) ?? {}),
    };
    const voiLUTFunction = properties.VOILUTFunction ?? properties.voiLUTFunction;
    if (voiLUTFunction !== undefined) {
        properties.VOILUTFunction = voiLUTFunction;
    }
    const presentation = (getViewportPresentation(viewport) ?? {});
    return {
        properties,
        rotation: presentation.rotation,
        flipHorizontal: presentation.flipHorizontal,
        flipVertical: presentation.flipVertical,
        currentImageId: viewport.getCurrentImageId(),
    };
}
